DO $$
DECLARE
  found text := '';
  n bigint;
BEGIN
  SELECT count(*) INTO n FROM activity_event WHERE NOT (event_type IN ('COMMENT_CREATED', 'COMMENT_DELETED', 'COMMENT_UPDATED', 'COMMIT_CREATED', 'ISSUE_CLOSED', 'ISSUE_CREATED', 'ISSUE_DELETED', 'ISSUE_LABELED', 'ISSUE_REOPENED', 'ISSUE_TYPED', 'ISSUE_UNLABELED', 'ISSUE_UNTYPED', 'PULL_REQUEST_CLOSED', 'PULL_REQUEST_DRAFTED', 'PULL_REQUEST_LABELED', 'PULL_REQUEST_MERGED', 'PULL_REQUEST_OPENED', 'PULL_REQUEST_READY', 'PULL_REQUEST_REOPENED', 'PULL_REQUEST_SYNCHRONIZED', 'PULL_REQUEST_UNLABELED', 'REVIEW_APPROVED', 'REVIEW_CHANGES_REQUESTED', 'REVIEW_COMMENTED', 'REVIEW_COMMENT_CREATED', 'REVIEW_COMMENT_DELETED', 'REVIEW_COMMENT_EDITED', 'REVIEW_DISMISSED', 'REVIEW_EDITED', 'REVIEW_THREAD_RESOLVED', 'REVIEW_THREAD_UNRESOLVED', 'REVIEW_UNKNOWN'));
  IF n > 0 THEN found := found || format(E'\n  %s.%s: %s', 'activity_event', 'event_type', n); END IF;
  IF found <> '' THEN
    RAISE EXCEPTION E'The upgrade stopped before it checks the stored rows of activity_event. Each column below holds rows with a value that the server cannot read, followed by their number:%\nCorrect or delete these rows, then start the upgrade again. The upgrade notes for this release give the query that lists them.', found;
  END IF;
END $$

